import { useEffect, useState, useCallback } from "react";

type Item = {
  id: number;
  name: string;
  bought: boolean;
};

export default function App() {
  const [items, setItems] = useState<Item[]>([]);
  const [name, setName] = useState("");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async () => {
    try {
      const res = await fetch("/api/items");
      if (!res.ok) throw new Error();
      const data: Item[] = await res.json();
      setItems(data);
      setError(null);
    } catch {
      setError("No se pudo conectar con el servidor");
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  const add = async () => {
    const trimmed = name.trim();
    if (!trimmed) return;
    try {
      const res = await fetch("/api/items", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ name: trimmed }),
      });
      if (!res.ok) throw new Error();
      const item: Item = await res.json();
      setItems((prev) => [...prev, item]);
      setName("");
      setError(null);
    } catch {
      setError("No se pudo agregar el ítem");
    }
  };

  const buy = async (id: number) => {
    try {
      const res = await fetch(`/api/items/${id}/bought`, { method: "POST" });
      if (!res.ok) throw new Error();
      const updated: Item = await res.json();
      setItems((prev) => prev.map((i) => (i.id === id ? updated : i)));
      setError(null);
    } catch {
      setError("No se pudo marcar como comprado");
    }
  };

  const remove = async (id: number) => {
    try {
      const res = await fetch(`/api/items/${id}`, { method: "DELETE" });
      if (!res.ok && res.status !== 404) throw new Error();
      setItems((prev) => prev.filter((i) => i.id !== id));
      setError(null);
    } catch {
      setError("No se pudo borrar el ítem");
    }
  };

  const pending = items.filter((i) => !i.bought).length;

  return (
    <div className="min-h-screen bg-gray-100 flex justify-center p-6">
      <div className="w-full max-w-md bg-white rounded-xl shadow p-6 h-fit">
        <h1 className="text-2xl font-bold mb-2">Lista de compras</h1>
        <p className="text-gray-600 mb-4">{pending} por comprar</p>

        <form
          className="flex gap-2 mb-4"
          onSubmit={(e) => {
            e.preventDefault();
            add();
          }}
        >
          <input
            className="flex-1 border rounded px-3 py-2"
            placeholder="Producto"
            value={name}
            onChange={(e) => setName(e.target.value)}
          />
          <button
            type="submit"
            className="bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700"
          >
            Agregar
          </button>
        </form>

        {error && <p className="text-red-600 mb-3">{error}</p>}
        {loading && <p className="text-gray-500">Cargando...</p>}

        <ul className="space-y-2">
          {items.map((item) => (
            <li
              key={item.id}
              className="flex items-center justify-between border rounded px-3 py-2"
            >
              <span className={item.bought ? "text-gray-400" : ""}>
                {item.name}
                {item.bought && <span className="ml-2 text-green-600">✓</span>}
              </span>
              <span className="flex gap-2">
                {!item.bought && (
                  <button
                    onClick={() => buy(item.id)}
                    className="bg-green-600 text-white px-3 py-1 rounded hover:bg-green-700"
                  >
                    Comprado
                  </button>
                )}
                <button
                  onClick={() => remove(item.id)}
                  className="bg-red-600 text-white px-3 py-1 rounded hover:bg-red-700"
                >
                  Borrar
                </button>
              </span>
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
}

